<?php require __DIR__.'/../app/bootstrap.php';require __DIR__.'/_layout.php';$u=require_admin();$id=(int)($_GET['id']??0);$msg='';$err='';$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c){http_response_code(404);die('Customer not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='status'){if($id===(int)$u['id'])throw new RuntimeException('You cannot disable your own account.');$st=($_POST['account_status']??'active')==='disabled'?'disabled':'active';db()->prepare('UPDATE users SET account_status=? WHERE id=?')->execute([$st,$id]);db()->prepare('INSERT INTO customer_activity(user_id,admin_user_id,action,details) VALUES(?,?,?,?)')->execute([$id,$u['id'],$st==='disabled'?'disable':'enable','Account status changed to '.$st]);$msg='Account status updated.';}elseif($a==='notes'){db()->prepare('UPDATE users SET admin_notes=? WHERE id=?')->execute([trim($_POST['admin_notes']??''),$id]);db()->prepare('INSERT INTO customer_activity(user_id,admin_user_id,action,details) VALUES(?,?,?,?)')->execute([$id,$u['id'],'notes','Admin notes updated.']);$msg='Admin notes saved.';}elseif($a==='security_reset_password'){if($id===(int)$u['id'])throw new RuntimeException('Use Account & Security to change your own password.');$p1=$_POST['new_password']??'';if(strlen($p1)<10)throw new RuntimeException('Temporary password must be at least 10 characters.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($p1,PASSWORD_DEFAULT),$id]);db()->prepare('DELETE FROM user_sessions WHERE user_id=?')->execute([$id]);$msg='Password reset. Give the temporary password to the customer securely.';}elseif($a==='security_reset_2fa'){db()->prepare('UPDATE users SET two_factor_secret=NULL,two_factor_enabled=0,two_factor_recovery_codes=NULL WHERE id=?')->execute([$id]);$msg='Customer 2FA reset.';}elseif($a==='impersonate'){if($id===(int)$u['id'])throw new RuntimeException('Already using this account.');if(($c['account_status']??'active')==='disabled')throw new RuntimeException('Enable this account before impersonating it.');$_SESSION['admin_return_uid']=$u['id'];$_SESSION['uid']=$id;header('Location: /');exit;}}catch(Throwable $e){$err=$e->getMessage();}$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$c=$q->fetch();}
function rows_for($sql,$id){$q=db()->prepare($sql);$q->execute([$id]);return $q->fetchAll();}$services=rows_for('SELECT * FROM services WHERE user_id=? ORDER BY id DESC',$id);$invoices=rows_for('SELECT * FROM invoices WHERE user_id=? ORDER BY id DESC LIMIT 20',$id);$orders=rows_for('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 20',$id);$tickets=rows_for('SELECT * FROM support_tickets WHERE user_id=? ORDER BY id DESC LIMIT 20',$id);$activity=rows_for('SELECT ca.*,a.name admin_name FROM customer_activity ca LEFT JOIN users a ON a.id=ca.admin_user_id WHERE ca.user_id=? ORDER BY ca.id DESC LIMIT 30',$id);admin_head($u,'Customer Profile','customers');?><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><div class="customer-hero card"><div><div class="eyebrow">CUSTOMER #<?=$c['id']?></div><h2><?=e($c['name'])?></h2><div class="muted"><?=e($c['email'])?> · Joined <?=e($c['created_at'])?></div></div><div><?=admin_badge($c['account_status']??'active')?></div></div><div class="customer-actions"><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="status"><select name="account_status"><option value="active" <?=($c['account_status']??'active')==='active'?'selected':''?>>Active</option><option value="disabled" <?=($c['account_status']??'active')==='disabled'?'selected':''?>>Disabled</option></select><button class="btn">Update account</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn primary" name="action" value="impersonate">Login as customer</button></form></div><section class="card settings-card"><div class="cardhead"><b>ACCOUNT SECURITY</b></div><div class="ticket-form"><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="security_reset_password"><input type="password" name="new_password" minlength="10" placeholder="Temporary password" required><button class="btn">Set temporary password</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn danger" name="action" value="security_reset_2fa" onclick="return confirm('Reset this customer’s two-factor authentication?')">Reset customer 2FA</button></form></div></section><section class="stats"><div class="stat"><span class="muted">Services</span><strong><?=count($services)?></strong></div><div class="stat"><span class="muted">Invoices</span><strong><?=count($invoices)?></strong></div><div class="stat"><span class="muted">Tickets</span><strong><?=count($tickets)?></strong></div></section><section class="card"><div class="cardhead"><b>ADMIN NOTES</b><span class="muted">Private</span></div><form method="post" class="ticket-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="notes"><textarea name="admin_notes" rows="4" placeholder="Private notes about this customer..."><?=e($c['admin_notes']??'')?></textarea><button class="btn">Save notes</button></form></section><?php foreach([['SERVICES',$services,['id','name','status','next_due_at']],['INVOICES',$invoices,['invoice_number','status','total','due_at']],['ORDERS',$orders,['order_number','status','total','created_at']],['TICKETS',$tickets,['id','subject','status','updated_at']]] as [$title,$rows,$cols]):?><section class="card"><div class="cardhead"><b><?=$title?></b><span class="muted"><?=count($rows)?></span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><?php foreach($cols as $col):?><th><?=e(strtoupper(str_replace('_',' ',$col)))?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($cols as $col):?><td><?=e($r[$col]??'—')?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></section><?php endforeach?><section class="card"><div class="cardhead"><b>ACTIVITY</b></div><div class="ticket-list"><?php foreach($activity as $a):?><div class="ticket-row"><div><b><?=e(ucwords(str_replace('_',' ',$a['action'])))?></b><small><?=e($a['details'])?> · <?=e($a['admin_name']?:'System')?> · <?=e($a['created_at'])?></small></div></div><?php endforeach?></div></section><?php admin_foot(); ?>
